html, body { margin: 0; padding: 0; }
body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 13px; color: #1f2937; background: #f6f7f9;
  height: calc(var(--appsmith-ui-height) * 1px); overflow: auto;
}
body.busy { cursor: progress; }
body.busy .spin { display: inline-block; }
#app { padding: 10px 14px 24px; }
.nav { display: flex; gap: 4px; align-items: center; flex-wrap: wrap; margin-bottom: 12px; padding-bottom: 8px; border-bottom: 1px solid #e5e7eb; }
