.b-grey { background: #e5e7eb; color: #374151; } .b-blue { background: #dbeafe; color: #1e40af; }
.b-amber { background: #fef3c7; color: #92400e; } .b-green { background: #d1fae5; color: #065f46; }
.b-red { background: #fee2e2; color: #991b1b; } .b-dark { background: #374151; color: #fff; }
