.grid2 { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 8px 16px; }
.kv .k { font-size: 11px; color: #6b7280; } .kv .v { font-weight: 600; }
#toast { position: fixed; right: 14px; bottom: 14px; max-width: 520px; padding: 10px 14px; border-radius: 8px; color: #fff; background: #065f46;
  white-space: pre-wrap; box-shadow: 0 4px 14px rgba(0,0,0,.2); opacity: 0; transform: translateY(10px); transition: all .2s; pointer-events: none; z-index: 50; }
#toast.show { opacity: 1; transform: none; }
#toast.err { background: #991b1b; }
.modal-wrap { position: fixed; inset: 0; background: rgba(17,24,39,.45); display: flex; align-items: center; justify-content: center; z-index: 40; }
.modal { background: #fff; border-radius: 10px; padding: 16px 18px; width: min(520px, 92vw); box-shadow: 0 10px 30px rgba(0,0,0,.25); }
.modal h3 { margin: 0 0 10px; font-size: 16px; }
.modal-body { margin-bottom: 14px; line-height: 1.5; white-space: normal; }
.modal-actions { display: flex; justify-content: flex-end; gap: 8px; }
.spin { display: none; width: 14px; height: 14px; border: 2px solid #93c5fd; border-top-color: #1d4ed8; border-radius: 50%; animation: sp 0.8s linear infinite; vertical-align: middle; }
@keyframes sp { to { transform: rotate(360deg); } }
.empty { padding: 30px; text-align: center; color: #6b7280; }
a.lnk { color: #1d4ed8; text-decoration: none; } a.lnk:hover { text-decoration: underline; }

